#!/usr/bin/env bash
# Question 1: Debug a Pod that has no shell. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/debug
mkdir -p /opt/course/debug
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" delete pod legacy-api --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"legacy-api"},"spec":{"terminationGracePeriodSeconds":1,"containers":[{"name":"app","image":"registry.k8s.io/pause:3.10"}]}}' >/dev/null
kubectl -n "${Q1_NS}" wait --for=condition=Ready pod/legacy-api --timeout=120s >/dev/null
kubectl -n "${Q1_NS}" get pod legacy-api -o jsonpath='{.metadata.uid}' > /root/.cka-debug-uid-${Q1_NS}
: "${Q1_NS}" "${Q1_NODE}"
